import React from 'react'
import { Row, Col, Button } from 'antd'

export default function SectionWrapper (props) {
  const {
    sectionHeading,
    buttonName,
    children
  } = props
  const buttonHandler = () => {
    props.buttonFunction()
  }
  return (
    <div>
      <Row type='flex' justify='space-between'>
        <Col>
          <h3><b>{sectionHeading}</b></h3>
        </Col>
        <Col>
          <Button type='primary' onClick={buttonHandler}>{buttonName}</Button>
        </Col>
      </Row>
      <Row type='flex' justify='center' className='table-section'>
        <Col span={22}>
          {children}
        </Col>
      </Row>
    </div>
  )
}
