import { get } from 'lodash'

export function finalPayload (data) {
  return data.map(item => {
    delete item.parent_product_attribute_id
    return item
  })
}

export const payloadMapper = (item, type) => {
  return {
    attribute_id: item.attribute_id,
    parent_attribute_id: item.parent_product_attribute_id,
    parent_product_attribute_id: item.parent_product_attribute_id,
    is_array: item.is_array === 'false' ? false : item.is_array,
    attribute_type: type
  }
}

export const payloadFormation = (data, type) => {
  const newPayload = []
  if (data.length > 0) {
    data.forEach((item, index) => {
      newPayload.push(payloadMapper(item, type))
      if (item.tableData.length > 0) {
        item.tableData.forEach(ele => {
          newPayload.push(payloadMapper(ele, type))
        })
      }
    })
  }
  return newPayload
}

export function tableFormationData (data, templateData) {
  let parentData = []
  function mapping (item, mainData) {
    if (mainData.length === 0) return
    if (Array.isArray(mainData)) {
      return mainData.map(el => {
        if (item.parent_product_attribute_id === el.attribute_id) {
          el.children.push(item)
        } else {
          mapping(item, el.children)
        }
        return el
      })
    }
  }
  function traverse (data) {
    for (let i = 0; i < data.length; i++) {
      if (data[i].parent_product_attribute_id !== null) {
        mapping(data[i], parentData)
      } else {
        parentData.push(data[i])
      }
    }
  }
  if (data.length > 0 && templateData.length > 0) {
    let mainData = data.map((item) => {
      let templateDataObject = templateData.find(ele => ele.id === item.attribute_id)
      return {
        ...item,
        code: templateDataObject.code,
        name: templateDataObject.name,
        datatype: templateDataObject.datatype
      }
    })
    let modifiedData = mainData.map((item, index) => {
      return {
        ...item,
        key: index,
        children: []
      }
    })
    traverse(modifiedData)
    if (get(parentData[0], 'children', []).length === 0) {
      delete parentData[0].children
    }
    return parentData
  }
}
export function childrenArrayRemoves (data, parentIndex = '') {
  for (let i = 0; i < data.length; i++) {
    if (data[i].children && data[i].children.length > 0) {
      data[i] = {
        ...data[i],
        key: parentIndex ? parseInt(`${parentIndex}${i + 1}`) : i + 1,
        children: data[i].children
      }
      childrenArrayRemoves(data[i].children, i + 1)
    } else {
      if (data[i].children && data[i].children.length === 0) {
        delete data[i].children
        data[i] = {
          ...data[i],
          key: parentIndex ? parseInt(`${parentIndex}${i + 1}`) : i + 1
        }
      }
    }
  }
  return data
}
export function templateName (id, templateData) {
  return templateData.find(item => item.id === id).name
}

export function uniqueData (newData, step2Data) {
  for (let i = 0; i < step2Data.length; i++) {
    for (let j = 0; j < newData.length; j++) {
      if (newData[j].attribute_id === step2Data[i].attribute_id) {
        if (i === 0) {
          newData = []
        } else {
          newData = newData.filter(item => item.attribute_id !== step2Data[i].attribute_id)
        }
      }
    }
  }
  return newData
}
