import React, { Component } from 'react'
import StepWrapper from '../../../components/Steps'
import Step2StyleWrapper from './index.style'
import { Row, Col, Button, notification, Spin } from 'antd'
import { connect } from 'react-redux'
import Step2Actions from '../../../../../redux/productConfig/actions'
import { get, size } from 'lodash'
import { tableFormationData, finalPayload, childrenArrayRemoves } from './PolicyCreationAttributes/dataFormation'
import SectionWrapper from './sectionWrapper'
import TableWrapper from '../../../components/Table'
import { Step2TableColumns } from '../../../constants/Step2Table'
import { uniquesAttributes } from '../../../util/dataUniqueness'
const {
  getAllProductAttributes,
  resetProductConfigRedux,
  productDetailsAttributes,
  addProductAttributesAction
} = Step2Actions

class Step2 extends Component {
  state = {
    step1Data: {},
    loadingTable: false,
    productAttributesTable: [],
    submissionPayload: [],
    policyCreationTableData: [],
    endorsementCreationTableData: []
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      templateData,
      templateDatamessage,
      addProductAttributes
    } = nextProps
    if (templateDatamessage === 'success') {
      const pacakageId = get(templateData, 'data.details', []).find(item => item.code === 'package_id') || {}
      const referenceId = get(templateData, 'data.details', []).find(item => item.code === 'reference_id') || {}
      const tableData = [pacakageId, referenceId].map(item => {
        return {
          attribute_id: item.id,
          attribute_type: 'creation',
          code: item.code,
          datatype: item.datatype,
          is_array: false,
          key: 0,
          name: item.name,
          parent_attribute_id: null,
          parent_product_attribute_id: null
        }
      })
      const submissionData = [pacakageId, referenceId].map(item => {
        return {
          attribute_id: item.id,
          attribute_type: 'creation',
          is_array: false,
          parent_attribute_id: null,
          parent_product_attribute_id: null
        }
      })
      this.setState({
        loadingTable: false,
        policyCreationTableData: tableData,
        submissionPayload: submissionData
      })
      window.sessionStorage.setItem('oldPolicyCreationData', JSON.stringify(tableData))
      window.sessionStorage.setItem('submissionItem', JSON.stringify(submissionData))
      window.sessionStorage.setItem('policyCreation', JSON.stringify(submissionData))

      this.props.resetProductConfigRedux(['templateDatamessage'])
    }
    if (addProductAttributes === 'success') {
      notification.success({
        message: 'Success',
        description: 'Product attributes created successfully'
      })
      this.props.resetProductConfigRedux(['addProductAttributes'])
      this.nextStep()
    }
    if (addProductAttributes !== 'success' && (addProductAttributes !== '' && addProductAttributes !== undefined)) {
      notification.error({
        message: 'Error',
        description: get(addProductAttributes, 'errors[0].description', '')
      })
      this.props.resetProductConfigRedux(['addProductAttributes'])
    }
  }

  componentDidMount () {
    const { location, templateData } = this.props
    const { step1Data } = this.state
    const payload = get(location, 'state', {})
    const formName = get(payload, 'formName', '')
    const localStep1Data = JSON.parse(window.sessionStorage.getItem('Step1'))

    if (size(step1Data) === 0 && size(localStep1Data) > 0) {
      this.setState({
        step1Data: localStep1Data
      })
    }
    switch (formName) {
      case 'Step1': {
        const step1Data = get(payload, 'formData.step1Data', {})
        window.sessionStorage.setItem('Step1', JSON.stringify(step1Data))
        this.setState({
          loadingTable: true,
          step1Data
        })
        this.props.getAllProductAttributes()
      }
        break
      case 'add-attributes-form': {
        const oldSubmissionData = JSON.parse(window.sessionStorage.getItem('submissionItem')) || []
        const newDataPayload = uniquesAttributes([...oldSubmissionData])
        this.setState({
          submissionPayload: newDataPayload
        })
        window.sessionStorage.setItem('submissionItem', JSON.stringify(newDataPayload))
        const oldDataPolicy = JSON.parse(window.sessionStorage.getItem('oldPolicyCreationData')) || []
        const oldDataEndorsement = JSON.parse(window.sessionStorage.getItem('oldEndorsementCreationData')) || []
        const newDataPolicy = uniquesAttributes([...oldDataPolicy])
        const newDataEndorsement = uniquesAttributes([...oldDataEndorsement])
        this.setState({
          policyCreationTableData: newDataPolicy,
          endorsementCreationTableData: newDataEndorsement
        })
        window.sessionStorage.setItem('oldPolicyCreationData', JSON.stringify(newDataPolicy))
        window.sessionStorage.setItem('oldEndorsementCreationData', JSON.stringify(newDataEndorsement))
      }
        break
      case 'policyCreation': {
        const policyCreationData = JSON.parse(window.sessionStorage.getItem('policyCreation')) || []
        if (size(policyCreationData) > 0) {
          const oldSubmissionData = JSON.parse(window.sessionStorage.getItem('submissionItem')) || []
          const newDataPayload = uniquesAttributes([...oldSubmissionData, ...policyCreationData])
          this.setState({
            submissionPayload: newDataPayload
          })
          window.sessionStorage.setItem('submissionItem', JSON.stringify(newDataPayload))
          const templateDetails = get(templateData, 'data.details', [])
          const tableData = tableFormationData(policyCreationData, templateDetails) || []
          const oldData = JSON.parse(window.sessionStorage.getItem('oldPolicyCreationData')) || []
          const newData = uniquesAttributes([...oldData, ...tableData])
          this.setState({
            policyCreationTableData: newData,
            endorsementCreationTableData: JSON.parse(window.sessionStorage.getItem('oldEndorsementCreationData')) || []
          })
          window.sessionStorage.setItem('oldPolicyCreationData', JSON.stringify(newData))
        }
      }
        break
      case 'endorsementCreation': {
        const endorsementCreationData = JSON.parse(window.sessionStorage.getItem('endorsementCreation')) || []
        if (size(endorsementCreationData) > 0) {
          const oldSubmissionData = JSON.parse(window.sessionStorage.getItem('submissionItem')) || []
          const newDataPayload = uniquesAttributes([...oldSubmissionData, ...endorsementCreationData])
          this.setState({
            submissionPayload: newDataPayload
          })
          window.sessionStorage.setItem('submissionItem', JSON.stringify(newDataPayload))
          const templateDetails = get(templateData, 'data.details', [])
          const tableData = tableFormationData(endorsementCreationData, templateDetails) || []
          const oldData = JSON.parse(window.sessionStorage.getItem('oldEndorsementCreationData')) || []
          const newData = uniquesAttributes([...oldData, ...tableData])
          this.setState({
            endorsementCreationTableData: newData,
            policyCreationTableData: JSON.parse(window.sessionStorage.getItem('oldPolicyCreationData')) || []
          })
          window.sessionStorage.setItem('oldEndorsementCreationData', JSON.stringify(newData))
        }
      }
        break
      default: {
        this.props.history.push({
          pathname: '/product-config/create-product/1'
        })
      }
    }
  }

  handlePreviousStep = () => {
    const { step1Data } = this.state

    const { history } = this.props

    history.push({
      pathname: '/product-config/create-product/1',
      state: {
        formName: 'Step2',
        step1Data
      }
    })
    window.sessionStorage.removeItem('oldEndorsementCreationData')
    window.sessionStorage.removeItem('oldPolicyCreationData')
    window.sessionStorage.removeItem('submissionItem')
  }

  nextStep = () => {
    const { step1Data } = this.state
    const { history } = this.props
    history.push({
      pathname: '/product-config/create-product/3',
      state: {
        formName: 'Step2',
        formData: step1Data
      }
    })
    window.sessionStorage.removeItem('submissionItem')
    window.sessionStorage.removeItem('Step1')
    window.sessionStorage.removeItem('oldEndorsementCreationData')
    window.sessionStorage.removeItem('oldPolicyCreationData')
    window.sessionStorage.removeItem('policyCreation')
    window.sessionStorage.removeItem('endorsementCreation')
  }

  handleCreateAttributes = () => {
    const { submissionPayload, step1Data } = this.state

    const productCode = get(step1Data, 'code')
    const finalPayloadData = uniquesAttributes(finalPayload(submissionPayload))

    this.props.addProductAttributesAction({
      query: { productCode: productCode },
      body: {
        payload: finalPayloadData,
        type: 'add'
      }
    })
  }

  policyCreationButtonHandler =() => {
    this.props.history.push({
      pathname: '/product-config/create-product/2/productAttributesForm',
      state: {
        formName: 'step2',
        formData: {
          type: 'creation',
          initialData: this.state.policyCreationTableData
        }
      }
    })
  }

  endorsementCreationButtonHandler = () => {
    this.props.history.push({
      pathname: '/product-config/create-product/2/productAttributesForm',
      state: {
        formName: 'step2',
        formData: {
          type: 'endorsement',
          initialData: this.state.endorsementCreationTableData
        }
      }
    })
  }
  // editPageAttributes = (val) => {
  //   const productCode = get(JSON.parse(window.sessionStorage.getItem('Step1')), 'code', '')
  //   this.props.history.push({
  //     pathname: `/product-config/edit/policy-creation/${productCode}`,
  //     state: {
  //       formName: 'detail-page-attributes',
  //       formData: val
  //     }
  //   })
  // }

  render () {
    const { addProductAttributesLoading, addProductAttributesError } = this.props
    const { policyCreationTableData, submissionPayload, endorsementCreationTableData, loadingTable } = this.state
    return (
      <Step2StyleWrapper>
        <Row type='flex' justify='center'>
          <Col span={20}>
            <StepWrapper
              current={1}
            >
              <div className='section-wrapper'>
                <div className='table-section'>
                  <SectionWrapper
                    sectionHeading='Policy Creation Data'
                    buttonName='Add Policy Creation Field'
                    buttonFunction={this.policyCreationButtonHandler}
                  >
                    <Spin spinning={loadingTable} tip='Loading....'>

                      <TableWrapper
                        bordered
                        columns={Step2TableColumns}
                        dataSource={childrenArrayRemoves(policyCreationTableData)}
                        pagination={false}
                      />
                    </Spin>
                  </SectionWrapper>
                </div>
                <div className='table-section'>
                  <SectionWrapper
                    sectionHeading='Endorsement Data'
                    buttonName='Add Endorsement Field'
                    buttonFunction={this.endorsementCreationButtonHandler}
                  >
                    <TableWrapper
                      bordered
                      columns={Step2TableColumns}
                      dataSource={childrenArrayRemoves(endorsementCreationTableData)}
                      pagination={false}
                    />
                  </SectionWrapper>
                </div>
                <Row type='flex' justify='center' className='bottom-buttons'>
                  <Col span={18}>
                    <Button onClick={this.handlePreviousStep}>Previous</Button>&nbsp;
                    <Button
                      type='primary'
                      loading={addProductAttributesLoading && !addProductAttributesError}
                      disabled={submissionPayload.length === 0}
                      onClick={this.handleCreateAttributes}
                    >
                      Next
                    </Button>
                  </Col>
                </Row>
              </div>
            </StepWrapper>
          </Col>
        </Row>
      </Step2StyleWrapper>
    )
  }
}

export default connect(
  state => ({
    templateData: state.ProductConfigurable.getAllProductAttributes,
    addProductAttributes: state.ProductConfigurable.addProductAttributesMessage,
    productDetailAttributesLoading: state.Loading.PRODUCT_DETAILS_ATTRIBUTE,
    productDetailAttributesError: state.Error.PRODUCT_DETAILS_ATTRIBUTE,
    addProductAttributesLoading: state.Loading.ADD_PRODUCT_ATTRIBUTES,
    addProductAttributesError: state.Error.ADD_PRODUCT_ATTRIBUTES,
    templateDatamessage: state.ProductConfigurable.getAllProductAttributesMessage
  }), {
    addProductAttributesAction,
    productDetailsAttributes,
    resetProductConfigRedux,
    getAllProductAttributes
  }
)(Step2)
